nina: ```python
# Python: streaming with simple retries
import time
from redwood import RedwoodClient
client = RedwoodClient(api_key="${RW_KEY}")

def stream_with_retries(prompt, max_attempts=4):
    for attempt in range(1, max_attempts + 1):
        try:
            for chunk in client.generate(prompt, stream=True):
                # chunk may have .text or .delta depending on SDK version
                print(getattr(chunk, 'text', getattr(chunk, 'delta', '')), end="", flush=True)
            return
        except (TimeoutError, ConnectionError) as e:
            backoff = 2 ** attempt
            time.sleep(backoff)
            if attempt == max_attempts:
                raise

# usage
# stream_with_retries("Summarize the following logs...")
```

nina: ```ts
// TypeScript: async streaming + retry helper + AbortController
import { Redwood } from "@redwood/inference";
const client = new Redwood({ apiKey: process.env.RW_KEY });

async function streamAndHandle(prompt: string) {
  const controller = new AbortController();
  // optional: cancel after 60s
  const timeout = setTimeout(() => controller.abort(), 60_000);
  try {
    // sdk returns an async iterable of events: { type: 'delta' | 'end' | 'meta', delta?: string }
    const stream = await client.responses.stream({ prompt }, { signal: controller.signal });
    for await (const evt of stream) {
      if (evt.type === 'delta') process.stdout.write(evt.delta);
      if (evt.type === 'end') console.log('\n-- stream complete --');
    }
  } finally {
    clearTimeout(timeout);
  }
}

// small retry wrapper
async function withRetries(fn, attempts = 3) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      await new Promise(r => setTimeout(r, 2 ** i * 100));
    }
  }
  throw lastErr;
}
```

nina: ```go
// Go: pagination pattern for list endpoints
resp, err := client.ListEmbeddings(ctx, &ListRequest{PageSize: 200})
if err != nil { return err }
for {
    for _, it := range resp.Items {
        fmt.Println(it.Id)
    }
    if resp.NextPageToken == "" { break }
    resp, err = client.ListEmbeddings(ctx, &ListRequest{PageToken: resp.NextPageToken, PageSize: 200})
    if err != nil { return err }
}
```

